        'user',
        '<command-message>skill</command-message>\n<command-name>/skill</command-name>\n<command-args>Keep this user request exactly.</command-args>',
      ),
      claudeRow('expanded', 'command', 'user', 'PRIVATE_IS_META_EXPANSION', {
